CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('member','editor','reviewer','publisher','admin')), created_at TEXT NOT NULL, deactivated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE TABLE password_resets (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, consumed_at TEXT);
CREATE TABLE shelves (user_id TEXT PRIMARY KEY REFERENCES users(id), version INTEGER NOT NULL, payload TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, payload TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX workspace_owner ON workspaces(user_id);
CREATE TABLE spaces (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('study','research')), title TEXT NOT NULL, description TEXT NOT NULL, version INTEGER NOT NULL, payload TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE space_members (space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')), PRIMARY KEY(space_id,user_id));
CREATE TABLE invitations (token_hash TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('editor','viewer')), max_uses INTEGER NOT NULL, uses INTEGER NOT NULL DEFAULT 0, expires_at TEXT NOT NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, title TEXT NOT NULL, instructions TEXT NOT NULL, record_ids TEXT NOT NULL, due_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE submissions (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, payload TEXT NOT NULL, feedback TEXT NOT NULL DEFAULT '', feedback_by TEXT REFERENCES users(id), updated_at TEXT NOT NULL, UNIQUE(task_id,user_id));
CREATE TABLE corrections (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), record_id TEXT NOT NULL, category TEXT NOT NULL, proposal TEXT NOT NULL, evidence_url TEXT NOT NULL, contact_email TEXT, status TEXT NOT NULL CHECK(status IN ('received','triaged','accepted','rejected','resolved')), moderation_note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE drafts (id TEXT PRIMARY KEY, record_id TEXT NOT NULL UNIQUE, author_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','submitted','source-checked','approved','rejected','withheld')), payload TEXT NOT NULL, content_hash TEXT NOT NULL, approved_hash TEXT, approved_by TEXT REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE TABLE draft_reviews (id TEXT PRIMARY KEY, draft_id TEXT NOT NULL REFERENCES drafts(id), reviewer_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, content_hash TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE public_records (record_id TEXT PRIMARY KEY, payload TEXT NOT NULL, content_hash TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('static','cms')), updated_at TEXT NOT NULL);
CREATE TABLE organizations (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, website TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('prospect','active','suspended')), version INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE rights (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), record_id TEXT NOT NULL, source_id TEXT NOT NULL, usage TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('requested','granted','expired','withdrawn')), expires_at TEXT, note TEXT NOT NULL, version INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE contracts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','review','active','ended','revoked')), starts_at TEXT, ends_at TEXT, note TEXT NOT NULL, version INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, job_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('publish','export','notification')), payload TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','completed','failed')), attempts INTEGER NOT NULL DEFAULT 0, next_at TEXT NOT NULL, locked_at TEXT, error_code TEXT, created_at TEXT NOT NULL, completed_at TEXT);
CREATE INDEX jobs_ready ON jobs(status,next_at);
CREATE TABLE artifacts (id TEXT PRIMARY KEY, payload TEXT NOT NULL, content_hash TEXT NOT NULL, generated_at TEXT NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, session_id TEXT, checkout_url TEXT, refunded_minor INTEGER NOT NULL DEFAULT 0, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,idempotency_key));
CREATE TABLE payment_events (event_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE refund_requests (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), amount_minor INTEGER NOT NULL, status TEXT NOT NULL, provider_id TEXT, UNIQUE(order_id,id));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_id TEXT, operation TEXT NOT NULL, target_id TEXT, status TEXT NOT NULL, request_id TEXT NOT NULL, created_at TEXT NOT NULL);
